{
  "root_cause": "The suggestion list items are focusable (tabindex='0'), so pressing Tab moves focus into the list instead of to the next form field.",
  "repair_strategy": "Modify the keydown handler to close the suggestion list when Tab is pressed while the list is open, allowing the default Tab action to skip the now-hidden list and reach the next field.",
  "edits": [
    {
      "path": "awesomplete.js",
      "sha256": "b60dd8ec51ae96e979d58de3e9681449056b74a3d44031eb1121f325bc2e3af6",
      "before": "        "keydown": function(evt) {
            var c = evt.keyCode;

            // If the dropdown `ul` is in view, then act on keydown for the following keys:
            // Enter / Esc / Up / Down
            if(me.opened) {
                if (c === 13 && me.selected) { // Enter
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 9 && me.selected && me.tabSelect) {
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 27) { // Esc
                    me.close({ reason: "esc" );
                }
                else if (c === 38 || c === 40) { // Down/Up arrow
                    evt.preventDefault();
                    me[c === 38? "previous" : "next"]();
                }
            }
        }",
      "after": "        "keydown": function(evt) {
            var c = evt.keyCode;

            // If the dropdown `ul` is in view, then act on keydown for the following keys:
            // Enter / Esc / Up / Down
            if(me.opened) {
                if (c === 13 && me.selected) { // Enter
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 9) {
                    me.close({ reason: "tab" });
                }
                else if (c === 9 && me.selected && me.tabSelect) {
                    evt.preventDefault();
                    me.select(undefined, undefined, evt);
                }
                else if (c === 27) { // Esc
                    me.close({ reason: "esc" );
                }
                else if (c === 38 || c === 40) { // Down/Up arrow
                    evt.preventDefault();
                    me[c === 38? "previous" : "next"]();
                }
            }
        }"
    }
  ],
  "expected_accessibility_effect": "When suggestions are visible, a single Tab press moves focus from the city input to the dietary requirements input, preserving logical focus order and complying with WCAG 2.1.1 Keyboard and 2.4.3 Focus Order.",
  "functional_risks": [
    "If a consumer has set tabSelect:true, the added Tab‑close will prevent the custom tab‑select behavior (though the default is false).",
    "Removing reliance on list-item tabindex may affect assistive technologies that expect focusable options, but arrow‑key navigation and aria-activedescendant remain unchanged."
  ],
  "verification_requirements": [
    "After typing 'Ber' in the city field, pressing Tab moves focus to the dietary requirements field.",
    "The suggestion list is closed after the Tab press.",
    "Arrow‑up/down navigation within the list still works when the list is open.",
    "Enter key still selects the highlighted suggestion and closes the list.",
    "Esc key still closes the list.",
    "Screen‑reader announcements for the list remain functional."
  ]
}

